{
	"type": "npm",
	"script": "${1:start}",
	"isBackground": true,
	"presentation": {
		"focus": true,
		"panel": "dedicated"
	},
	"group": {
		"kind": "build",
		"isDefault": true
	},
	"problemMatcher": {
		"owner": "typescript",
		"source": "ts",
		"applyTo": "closedDocuments",
		"fileLocation": ["relative", "\${cwd\}"],
		"pattern": "\$tsc",
		"background": {
			"activeOnStart": true,
			"beginsPattern": {
				"regexp": "(.*?)"
			},
			"endsPattern": {
				"regexp": "Compiled |Failed to compile."
			}
		}
	}
}

